const MAX_ITEMS = 20;       // how many articles you want
const MIN_TITLE_LEN = 30;   // ignore super short titles
const MIN_DESC_LEN = 80;    // ignore super short descriptions
const HOURS_BACK = 24;      // only keep items from last X hours

function isRecent(pubDate) {
  if (!pubDate) return true;
  const ts = Date.parse(pubDate);
  if (isNaN(ts)) return true;
  const cutoff = Date.now() - HOURS_BACK * 60 * 60 * 1000;
  return ts >= cutoff;
}

const seenLinks = new Set();
let filtered = [];

for (const item of items) {
  const j = item.json;
  const title = j.title || '';
  const desc =
    j.description ||
    j.content ||
    j['content:encoded'] ||
    '';
  const link = j.link || j.url || '';

  // drop items with no URL
  if (!link) continue;

  // drop very short / low-info items
  if (title.length < MIN_TITLE_LEN && desc.length < MIN_DESC_LEN) continue;

  // drop old items
  if (!isRecent(j.pubDate || j.date || j.isoDate)) continue;

  // dedupe by link
  if (seenLinks.has(link)) continue;
  seenLinks.add(link);

  filtered.push(item);
}

// Google News already ranks results.
// Keep only the first N as "top" articles.
return filtered.slice(0, MAX_ITEMS);

