// We assume the OpenAI node is right before this Code node
// and we get its JSON output in items[0].json
const data = items[0].json;

// --- Helper: recursively find the first LLM "text" field ---

function findBriefing(obj) {
  if (!obj || typeof obj !== 'object' || obj === null) return null;

  if (typeof obj.text === 'string' && obj.text.trim().length > 0) {
    return obj.text;
  }

  for (const key of Object.keys(obj)) {
    const val = obj[key];

    if (Array.isArray(val)) {
      for (const v of val) {
        const res = findBriefing(v);
        if (res) return res;
      }
    } else if (typeof val === 'object') {
      const res = findBriefing(val);
      if (res) return res;
    }
  }

  return null;
}

const raw = findBriefing(data) || 'No briefing text found.';

// --- Split raw text into: narrative + [SOURCES] + [KEYWORDS] blocks ---

let narrativeText = raw;
let sources = [];
let keywords = [];

// Strip code fences like ```markdown and ```
narrativeText = narrativeText
  .replace(/```markdown/gi, '')
  .replace(/```/g, '');

// Match [SOURCES] block
const sourcesMatch = raw.match(/\[SOURCES\]([\s\S]*?)(?:\[KEYWORDS\]|\s*$)/i);
if (sourcesMatch) {
  const block = sourcesMatch[1]
    .split('\n')
    .map(l => l.trim())
    .filter(l => l.length > 0);

  block.forEach(line => {
    const parts = line.split('|').map(p => p.trim());
    if (parts[0]) {
      sources.push({
        name: parts[0],
        count: parts[1] || '',
      });
    }
  });

  // Remove the whole [SOURCES]... part from narrative
  narrativeText = narrativeText.replace(sourcesMatch[0], '').trim();
}

// Match [KEYWORDS] block
const keywordsMatch = raw.match(/\[KEYWORDS\]([\s\S]*)$/i);
if (keywordsMatch) {
  const block = keywordsMatch[1].replace(/```/g, '').trim();
  keywords = block
    .split(',')
    .map(k => k.trim())
    .filter(k => k.length > 0);

  // Remove [KEYWORDS] from narrative too
  narrativeText = narrativeText.replace(keywordsMatch[0], '').trim();
}

// --- Convert narrative Markdown-ish text to HTML ---

let narrativeHtml = narrativeText;

// **bold** -> <strong>
narrativeHtml = narrativeHtml.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

// line breaks to <br>
narrativeHtml = narrativeHtml
  .replace(/\r\n/g, '\n')
  .replace(/\n\n/g, '<br><br>')
  .replace(/\n/g, '<br>');

