// --- RETURN AS BINARY HTML FOR RESPOND TO WEBHOOK ---

const base64 = Buffer.from(html, 'utf8').toString('base64');

return [
  {
    json: {},
    binary: {
      data: {
        data: base64,
        mimeType: 'text/html',
      },
    },
  },
];

// We get many items, each representing one article.
// We want to combine them into ONE item with a big text field.

const articles = items.map((item, index) => {
  const j = item.json;
  return `Article ${index + 1}:
Title: ${j.title || ''}
Source: ${j.source || ''}
Published: ${j.publishedAt || j.pubDate || ''}
Summary: ${j.summary || j.contentSnippet || ''}
Link: ${j.link || ''}`;
});

const articlesText = articles.join('\n\n');

// Return a SINGLE item that contains the combined articles text
return [
  {
    json: {
      articlesText,
    },
  },
];
